<div class="page-heading"><div><div class="eyebrow">ADMINISTRATION</div><h1>Admin accounts</h1><p>Every admin can manage articles, categories, and accounts.</p></div></div>
<?php if($error): ?><div class="notice error" role="alert"><?=e($error)?></div><?php endif; ?>
<?php $accounts=array_merge([['id'=>null,'username'=>'','display_name'=>'','active'=>1]],$admins);foreach($accounts as $account):$key=$account['id'] ?? 'new'; ?>
<section class="settings-card"><h2><?=$account['id'] ? e($account['display_name']) : 'Add an admin'?></h2><form class="account-form" method="post" action="<?=e(route_url('admins'))?>"><?=csrf_field()?><?php if($account['id']): ?><input type="hidden" name="id" value="<?=$account['id']?>"><?php endif; ?><div><label for="user-<?=$key?>">Username</label><input id="user-<?=$key?>" name="username" value="<?=e($account['username'])?>" required maxlength="80" autocomplete="off"></div><div><label for="name-<?=$key?>">Display name</label><input id="name-<?=$key?>" name="display_name" value="<?=e($account['display_name'])?>" required maxlength="120"></div><div><label for="pass-<?=$key?>"><?=$account['id']?'New password':'Password'?></label><input id="pass-<?=$key?>" type="password" name="password" autocomplete="new-password" minlength="8" maxlength="72" <?=$account['id']?'':'required'?>><p class="field-help"><?=$account['id']?'Leave blank to keep the current password.':'Use at least 8 characters.'?></p></div><div><label for="active-<?=$key?>">Status</label><select id="active-<?=$key?>" name="active"><option value="1" <?=$account['active']?'selected':''?>>Active</option><option value="0" <?=!$account['active']?'selected':''?>>Disabled</option></select></div><button class="button <?=$account['id']?'secondary':'primary'?>" type="submit"><?=$account['id']?'Save account':'Create admin'?></button></form></section><?php endforeach; ?>
